// V3 — Parsing + validation stricte du BROUILLON (première invocation LLM).
// Reconstruit la forme canonique des sept sections (clés connues uniquement),
// valide chaque Claim, rejette les blocs et rubriques interdits par le contrat
// V3, puis catalogue les claims par leur chemin canonique pour la vérification.
// Ce nœud NE publie rien : sa sortie est un brouillon a verifier.
const response = $input.first().json;
const upstream = $('V3 Assemble Draft Prompt').first().json;

const textBlock = (response.content || []).find((b) => b.type === 'text');
const content = textBlock && textBlock.text;
if (!content) throw new Error('Le LLM (brouillon) a renvoye un contenu vide');

if (response.stop_reason === 'max_tokens') {
  throw new Error('Reponse LLM (brouillon) tronquee (plafond de tokens) : brouillon incomplet, non exploitable.');
}

function extractJsonPayload(rawText) {
  let text = String(rawText).trim();
  const fenced = text.match(/```[a-zA-Z]*\s*([\s\S]*?)```/);
  if (fenced) text = fenced[1].trim();
  else text = text.replace(/```[a-zA-Z]*\s*/g, '').replace(/```/g, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start !== -1 && end > start) text = text.slice(start, end + 1);
  return text;
}

let parsed;
const payload = extractJsonPayload(content);
try {
  parsed = JSON.parse(payload);
} catch (e) {
  throw new Error('Reponse LLM (brouillon) non-JSON (' + e.message + ') — debut: ' + payload.slice(0, 160));
}

if (parsed.schema_version !== 3) throw new Error('schema_version du brouillon doit valoir 3');

// Blocs explicitement bannis du flux V3.
for (const banned of ['organisation', 'commercial_relationship', 'operational_activities']) {
