// Catalogue déterministe des claims du brouillon (même ordre que collectAccountKnowledgeV3Claims).
function collectV3Claims(c) {
  const out = [];
  function pn(claim, path) { if (claim !== null && claim !== undefined) out.push({ path: path, claim: claim }); }
  function pa2(claims, base) { (claims || []).forEach((claim, i) => out.push({ path: base + '[' + i + ']', claim: claim })); }
  pn(c.account_summary, '$.account_summary');
  const i = c.identity;
  pn(i.company_name, '$.identity.company_name'); pn(i.legal_name, '$.identity.legal_name');
  pn(i.primary_activity, '$.identity.primary_activity'); pn(i.headquarters, '$.identity.headquarters');
  pn(i.sector, '$.identity.sector'); pn(i.business_segment, '$.identity.business_segment');
  pn(i.revenue, '$.identity.revenue'); pn(i.employee_count, '$.identity.employee_count');
  pa2(i.geographic_reach, '$.identity.geographic_reach');
  const m = c.market_positioning;
  pn(m.account_positioning, '$.market_positioning.account_positioning');
  pn(m.competitive_environment, '$.market_positioning.competitive_environment');
  pa2(m.direct_competitors, '$.market_positioning.direct_competitors');
  pa2(m.competitive_advantages, '$.market_positioning.competitive_advantages');
  pa2(m.opportunities, '$.market_positioning.opportunities');
  pa2(m.threats, '$.market_positioning.threats');
  const p = m.policy_and_ambitions; const pb = '$.market_positioning.policy_and_ambitions';
  pn(p.purpose, pb + '.purpose'); pn(p.philosophy, pb + '.philosophy');
  pa2(p.culture, pb + '.culture'); pa2(p.public_statements, pb + '.public_statements');
  pa2(p.ambitions, pb + '.ambitions'); pa2(p.strategic_axes, pb + '.strategic_axes');
  pa2(p.leadership_posture, pb + '.leadership_posture'); pn(p.claimed_identity, pb + '.claimed_identity');
  const o = c.offers_and_customers;
  pn(o.core_business, '$.offers_and_customers.core_business');
  pa2(o.offers, '$.offers_and_customers.offers'); pa2(o.covered_domains, '$.offers_and_customers.covered_domains');
  pa2(o.services, '$.offers_and_customers.services'); pa2(o.service_models, '$.offers_and_customers.service_models');
  pa2(o.complementary_activities, '$.offers_and_customers.complementary_activities');
  pa2(o.uncovered_activities, '$.offers_and_customers.uncovered_activities');
  pn(o.customer_profile, '$.offers_and_customers.customer_profile');
  pa2(o.customer_segments, '$.offers_and_customers.customer_segments');
  pa2(o.segment_weights, '$.offers_and_customers.segment_weights');
  pa2(o.behavioral_trends, '$.offers_and_customers.behavioral_trends');
