  pa2(v.key_links, '$.value_chain.key_links'); pa2(v.critical_partners_or_suppliers, '$.value_chain.critical_partners_or_suppliers');
  pa2(v.dependencies, '$.value_chain.dependencies'); pa2(v.vulnerabilities, '$.value_chain.vulnerabilities');
  pn(v.end_customer_relationship, '$.value_chain.end_customer_relationship');
  const r = c.regulatory_environment;
  pa2(r.current_regulations, '$.regulatory_environment.current_regulations');
  pa2(r.required_certifications, '$.regulatory_environment.required_certifications');
  pa2(r.compliance_risks, '$.regulatory_environment.compliance_risks');
  pn(c.trends_and_news.analysis, '$.trends_and_news.analysis');
  return out;
}

